const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
  const url = 'http://127.0.0.1:4174/';
  async function shot(name, mutate) {
    await page.goto(url, { waitUntil: 'networkidle' });
    await page.evaluate(() => document.fonts.ready);
    if (mutate) await page.evaluate(mutate);
    await page.evaluate(() => document.fonts.ready);
    await page.waitForTimeout(100);
    await page.screenshot({ path: process.env.TMPDIR + '/variant_' + name + '.png', fullPage: true });
    // report measured text widths/weights
    const info = await page.evaluate(() => {
      const h1 = document.querySelector('.hero-copy h1');
      const brand = document.querySelector('.brand-name');
      const btn = document.querySelector('.hero-actions .btn');
      return {
        h1: [getComputedStyle(h1).fontWeight, h1.getBoundingClientRect().height],
        brandW: brand.getBoundingClientRect().width,
        btnW: btn.getBoundingClientRect().width,
        fontStatus: document.fonts.check('16px "Acme Sans"'),
      };
    });
    console.log(name, JSON.stringify(info));
  }
  // control
  await shot('control', null);
  // patch the @font-face rule's weight descriptor
  const patch = (range) => `(() => {
    for (const sheet of document.styleSheets) {
      let rules; try { rules = sheet.cssRules } catch { continue }
      for (let i = 0; i < rules.length; i++) {
        const r = rules[i];
        if (r.type === CSSRule.FONT_FACE_RULE && r.style.fontFamily.includes('Acme Sans')) {
          r.style.fontWeight = ${JSON.stringify(range)};
        }
      }
    }
  })()`;
  await shot('range300_900', patch('300 900'));
  await shot('range100_900', patch('100 900'));
  await shot('range400', patch('400'));
  await browser.close();
})();
EOF
